1100	/* The verdicts caused by a control the user owns — a meal break, the day's
1101	 * start or end. Each is drawn as a button that carries you to the setting
1102	 * responsible (see wireConflictJumps), because the useful next move on
1103	 * "Lunch conflict" is to look at your lunch. */
1104	const CONFLICT_KINDS = {
1105	  early: { label: "Too early", control: "ctlDayStart" },
1106	  late: { label: "Too late", control: "ctlDayEnd" },
1107	  lunch: { label: "Lunch conflict", control: "mealLunchStart" },
1108	  dinner: { label: "Dinner conflict", control: "mealDinnerStart" },
1109	  meal: { label: "Meal conflict", control: "mealLunchStart" },
1110	};
1111	
1112	/* The combo verdict names each culpable control; two vocabularies because the
1113	 * pill has ~14 characters of column and the tip title has room for full words. */
1114	const COMBO_SHORT = { lunch: "lunch", dinner: "dinner", early: "early", late: "late" };
1115	const COMBO_FULL = { lunch: "Lunch break", dinner: "Dinner break", early: "Day start", late: "Day end" };
1116	
1117	/** "Lunch + late" — the combo pill's label. Three or more culprits (or none
1118	 *  nameable, when every performance trips two settings at once) collapse to the
1119	 *  control groups, since the point is "several of your settings", not a list. */
1120	function comboLabel(kinds) {
1121	  if (kinds.length === 2) {
1122	    const s = kinds.map((k) => COMBO_SHORT[k]).join(" + ");
1123	    return s.charAt(0).toUpperCase() + s.slice(1);
1124	  }
1125	  const mealsOn = state.mealBreaks.some((m) => m.enabled !== false);
1126	  return mealsOn ? "Hours + meals" : "Day hours";
1127	}
1128	
1129	/** The kinds a combo pill's click should light up. An empty list (no single
1130	 *  culprit) means the settings gang up in pairs — flash all of them. */
1131	function comboJumpKinds(kinds) {
1132	  if (kinds.length) return kinds;
1133	  const all = ["early", "late"];
1134	  for (const m of state.mealBreaks) if (m.enabled !== false && CONFLICT_KINDS[m.id]) all.push(m.id);
1135	  return all;
1136	}
1137	
1138	/** The status pill HTML for a lane verdict (see laneStatus for the kinds). */
1139	function statusPillHTML(status) {
1140	  // No native title attributes — those are the browser's ugly tooltip; the short
1141	  // pill label carries the verdict on its own, and the conflict pills below
1142	  // open a real explanation on hover (see conflictTipHTML).
1143	  const conflict = CONFLICT_KINDS[status.kind];
1144	  if (conflict) {
1145	    return (
1146	      `<button type="button" class="st-blocked st-conflict" data-conflict="${status.kind}">` +
1147	      `<span class="st-warn" aria-hidden="true">▲</span>${conflict.label}</button>`
1148	    );
1149	  }
1150	  if (status.kind === "combo") {
1151	    return (
1152	      `<button type="button" class="st-blocked st-conflict" data-conflict="combo" data-kinds="${status.kinds.join(",")}">` +
1153	      `<span class="st-warn" aria-hidden="true">▲</span>${comboLabel(status.kinds)}</button>`
1154	    );
1155	  }
1156	  switch (status.kind) {
1157	    case "scheduled":
1158	      return `<span class="st-plan">&check;&nbsp;Scheduled!</span>`;
1159	    case "cantfit":
1160	      return `<span class="st-cant">Can't fit</span>`;
1161	    case "sold":
1162	      return `<span class="st-sold">Sold out</span>`;
1163	    case "baddates":
1164	    default:
1165	      return `<span class="st-dates">📅 No dates</span>`;
1166	  }
1167	}
1168	
1169	/**
1170	 * Play the one-shot "this just entered the plan" swell on a day mark. The class
1171	 * is stripped first (and a reflow forced) so a mark that wins the slot twice in
1172	 * quick succession restarts the animation rather than sitting still — without
1173	 * that, `add` on an already-present class is a no-op.
1174	 */
1175	function flashLockIn(seg) {
1176	  seg.classList.remove("seg--justlocked");
1177	  void seg.offsetWidth; // reflow: makes the re-add a fresh animation
1178	  seg.classList.add("seg--justlocked");
1179	  seg.addEventListener("animationend", () => seg.classList.remove("seg--justlocked"), { once: true });
1180	}
1181	
1182	/**
1183	 * Update each lane's state and right-hand verdict (see laneStatus for the
1184	 * kinds). The lane also mirrors the plan on its performance marks, and a forced
1185	 * (must-see) lane carries a pin.
1186	 */
