  cachedFetchJson(DATA_URL, CATALOGUE_TTL_MS, noteCache),
  cachedFetchJson(VENUES_URL, LOOKUPS_TTL_MS, noteCache),
  cachedFetchJson(AVAILABILITY_URL, AVAILABILITY_TTL_MS, noteCache),
]);

