cd /tmp/claude-0/-home-user-EdFringeNow/8570763d-85d2-530f-934e-cffbdfb41b21/scratchpad && cat > verify.mjs <<'EOF'
import fs from "fs";
import { chromium } from "playwright";
const wire = JSON.parse(fs.readFileSync("/home/user/EdFringeNow/data/normalized/shows.min.json"));
const walt = wire.find(r => r.t === "Walt Unfrozen").sl;
const slugs = [walt, ...wire.filter(r => (r.p||[]).length >= 10).slice(0, 9).map(r => r.sl)];
const b = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome" });

async function run(label, { blockAvailability = false, passes = 1 } = {}) {
  const pg = await (await b.newContext()).newPage();
  if (blockAvailability) await pg.route("**/availability.min.json", r => r.abort());
  const errs = [];
  pg.on("console", m => { const t = m.text(); if (/unavailable|data cache/.test(t)) errs.push(t.slice(0,110)); });
  await pg.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8899/plan/", { waitUntil: "domcontentloaded" });
  await pg.evaluate(({slugs}) => {
    localStorage.setItem("edfringe.plan.favourites.v1", JSON.stringify({v:1, slugs, filename:"t.csv", savedAt: Date.now()}));
    localStorage.setItem("edfringe.plan.prefs.v1", JSON.stringify({v:1, d0:13, d1:25}));
  }, {slugs});
  for (let i = 0; i < passes; i++) { await pg.reload({ waitUntil: "networkidle" }); await pg.waitForTimeout(2500); }
  const out = await pg.evaluate(() => {
    const tally = {};
    const segTally = {};
    for (const l of document.querySelectorAll(".lane")) {
      const st = l.querySelector(".lane-status")?.textContent.trim();
      tally[st] = (tally[st]||0)+1;
      for (const s of l.querySelectorAll(".seg")) { const c = s.className.replace("seg ","").split(" ")[0]; segTally[c]=(segTally[c]||0)+1; }
    }
    const err = document.getElementById("errorState");
    return { tally, segTally, lanes: document.querySelectorAll(".lane").length,
             errorPanelShown: err && !err.hidden, errorText: err && !err.hidden ? err.textContent.replace(/\s+/g," ").trim() : null };
  });
  console.log(`\n### ${label}`);
  console.log("  lanes:", out.lanes, "| error panel:", out.errorPanelShown ? "SHOWN — " + out.errorText : "hidden");
  if (out.lanes) { console.log("  verdicts:", JSON.stringify(out.tally)); console.log("  marks:", JSON.stringify(out.segTally)); }
  if (errs.length) console.log("  console:", errs.join(" / "));
  await pg.screenshot({ path: label.replace(/\W+/g,"-") + ".png" });
}

await run("A normal load", { passes: 1 });
await run("B warm cache (3 loads)", { passes: 3 });
await run("C availability unreachable", { blockAvailability: true });
await b.close();
EOF
