import fs from "fs";
import { chromium } from "playwright";
const wire = JSON.parse(fs.readFileSync("/home/user/EdFringeNow/data/normalized/shows.min.json"));
const walt = wire.find(r => r.t === "Walt Unfrozen").sl;
const slugs = [walt, ...wire.filter(r => (r.p||[]).length >= 10).slice(0, 9).map(r => r.sl)];
const b = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome" });

async function run(label, poison) {
  const pg = await (await b.newContext()).newPage();
  const reqs = [];
  pg.on("request", r => { if (/\.json/.test(r.url())) reqs.push(r.url().split("/").pop()); });
  await pg.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8899/plan/", { waitUntil: "domcontentloaded" });
  await pg.evaluate(({slugs}) => {
    localStorage.setItem("edfringe.plan.favourites.v1", JSON.stringify({v:1, slugs, filename:"t.csv", savedAt: Date.now()}));
    localStorage.setItem("edfringe.plan.prefs.v1", JSON.stringify({v:1, d0:13, d1:25}));
  }, {slugs});
  await pg.reload({ waitUntil: "networkidle" });   // populate the cache
  await pg.waitForTimeout(2500);
  if (poison) await pg.evaluate(poison);
  reqs.length = 0;
  await pg.reload({ waitUntil: "networkidle" });
  await pg.waitForTimeout(2500);
  const out = await pg.evaluate(() => {
    const tally = {}; let red = 0, ok = 0;
    for (const l of document.querySelectorAll(".lane")) {
      tally[l.querySelector(".lane-status")?.textContent.trim()] = (tally[l.querySelector(".lane-status")?.textContent.trim()]||0)+1;
      for (const s of l.querySelectorAll(".seg")) (s.className.includes("seg-sold") ? red++ : ok++);
    }
    const e = document.getElementById("errorState");
    return { tally, red, ok, lanes: document.querySelectorAll(".lane").length, err: e && !e.hidden };
  });
  console.log(`\n### ${label}`);
  console.log("  refetched:", reqs.length ? [...new Set(reqs)].join(", ") : "(nothing — all cache hits)");
  console.log("  lanes:", out.lanes, "| error panel:", out.err ? "SHOWN" : "hidden", "| status-unknown marks:", out.red);
  if (out.lanes) console.log("  verdicts:", JSON.stringify(out.tally));
  await pg.screenshot({ path: label.replace(/\W+/g,"-") + ".png" });
}

